#!/usr/bin/env python3
# luxarch:worktree-create hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Create an agent worktree at its home beside the repository, `<repo parent>/.worktrees/<repo>/<KEY>`
(`_worktree_git.agents_home`), for `worktree.py add` and for Claude Code's WorktreeCreate event
(EnterWorktree, `claude --worktree`, a subagent's `isolation: "worktree"`), which hands creation to
this hook and works in the path it prints.

The handler replaces Claude Code's own creation, so it does what that did and what a checkout
outside the repository needs:
  * the branch is `worktree-<KEY>`, from the start commit the caller names (an existing branch of
    that name is checked out as it is, never reset);
  * a name already in use names the worktree `git worktree list` lists for THIS repository (at its
    home, or at `.claude/worktrees/<KEY>` from before the move), which the caller hands only to the
    session that holds it (`worktree.py` refuses one a live session holds, and names `adopt` for one
    whose session is gone); any other directory at the home is refused, never adopted or overwritten;
  * the home's parent must be outside every git checkout: inside one, the worktrees would be another
    repository's untracked files;
  * the main checkout's ignored files Claude Code carries into a worktree are copied in, once, at
    creation: `.claude/settings.local.json`, every file `.worktreeinclude` names that git ignores,
    and the ignored instruction files Claude Code reads from a directory above its own (`CLAUDE.md`,
    `.claude/CLAUDE.md`), which a worktree beside the repository has no main checkout above it to
    read. A copy, never a link (an edit through a link rewrites the owner's file); a file the
    worktree's own branch tracks or holds already is left alone, and nothing is written through a
    symlink. The sha256 of each copy is recorded in the worktree's git dir. A copy equal to the main
    checkout's current file is not work (`blockers`); a config copy (`CONFIG_COPIES`) still equal
    to its record is not work either while main holds that file; any other copy is work.

Stated limit: a copy is the main checkout's file as it was when the worktree was made; a later
change there does not reach it.

Python 3.9 and the standard library only, like the hook that loads it.
"""

from __future__ import annotations

import contextlib
import hashlib
import json
import re
import shutil
import subprocess
from pathlib import Path

from _worktree_git import (
    agent_worktree,
    agents_home,
    git_env,
    is_listed,
    listed_worktrees,
    out,
    run,
)

# a path that cannot be resolved (gone, a link loop)
_PATH_ERRORS = (OSError, RuntimeError)
# a copies record that cannot be read, or is not JSON
_RECORD_ERRORS = (OSError, ValueError)
WORKTREE_NAME = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,99}$")

# Claude Code reads these from every directory above the one it works in.
ANCESTOR_LOADED = ("CLAUDE.md", ".claude/CLAUDE.md")
# Claude Code copies this into every worktree it creates.
SETTINGS_LOCAL = ".claude/settings.local.json"
# The copies of Claude Code's own config: the only ones whose recorded digest makes an unchanged
# copy not work after the owner changes the main checkout's file (`copied_unchanged`).
CONFIG_COPIES = (SETTINGS_LOCAL, *ANCESTOR_LOADED)
# In the worktree's git dir: the sha256 of each file `copy_local` made, so a copy nobody changed is
# not work after the owner changes the main checkout's file.
COPIES = "luxarch-copies.json"


def _digest(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()


def _copies_file(wt: Path) -> Path | None:
    gitdir = out(wt, "rev-parse", "--absolute-git-dir")
    return Path(gitdir) / COPIES if gitdir else None


def copied_unchanged(wt: Path, rel: str) -> bool:
    """`rel` in the worktree at `wt` is a regular file `copy_local` made and nobody has changed: its
    sha256 is the one recorded when it was copied."""
    record = _copies_file(wt)
    f = wt / rel
    try:
        if record is None or f.is_symlink() or not f.is_file():
            return False
        data = json.loads(record.read_text(encoding="utf-8"))
        return isinstance(data, dict) and data.get(rel) == _digest(f)
    except _RECORD_ERRORS:
        return False


def _resolved(p: Path) -> Path:
    try:
        return p.resolve()
    except _PATH_ERRORS:
        return p


def home_refusal(main: Path) -> str:
    """Why `main`'s agent worktrees cannot live at its home, or "": the home's parent is inside a
    git checkout (this repository's own parent, a superproject)."""
    parent = main.parent
    top = out(parent, "rev-parse", "--show-toplevel") if parent.is_dir() else ""
    if top:
        return (
            f"{parent} is inside the git checkout {top}, so worktrees at "
            f"{agents_home(main)} would be its untracked files"
        )
    return ""


def _ignored_in(wt: Path, rel: str) -> bool:
    # check-ignore refuses --literal-pathspecs (run's), so `./` keeps a leading `:` literal
    r = subprocess.run(
        ["git", "-C", str(wt), "check-ignore", "-q", "--", f"./{rel}"],
        capture_output=True,
        text=True,
        env=git_env(),
    )
    return r.returncode == 0


def local_files(main: Path) -> list[str]:
    """The main checkout's files a new worktree is given a copy of (repo-relative): the settings
    Claude Code copies, the ignored files `.worktreeinclude` names, the ignored ancestor-loaded
    instruction files."""
    rels = [SETTINGS_LOCAL]
    include = main / ".worktreeinclude"
    if include.is_file() and not include.is_symlink():
        named = out(
            main, "ls-files", "--others", "--ignored", f"--exclude-from={include}"
        )
        rels += [r for r in named.splitlines() if r and _ignored_in(main, r)]
    rels += [r for r in ANCESTOR_LOADED if _ignored_in(main, r)]
    seen: list[str] = []
    for r in rels:
        if r not in seen:
            seen.append(r)
    return seen


def copy_local(main: Path, wt: Path) -> list[str]:
    """Copy `local_files(main)` into the worktree at `wt`, where each is a regular file in main, is
    absent from the worktree, is ignored on the worktree's branch too, and its directory resolves
    inside the worktree. Returns the paths copied."""
    root = _resolved(wt)
    made: list[str] = []
    for rel in local_files(main):
        src, dst = main / rel, wt / rel
        if src.is_symlink() or not src.is_file():
            continue
        if dst.exists() or dst.is_symlink() or not _ignored_in(wt, rel):
            continue
        parent = dst.parent
        try:
            parent.mkdir(parents=True, exist_ok=True)
        except OSError:
            continue
        real = _resolved(parent)
        if real != root and root not in real.parents:
            continue
        try:
            shutil.copy2(src, dst, follow_symlinks=False)
        except OSError:
            continue
        made.append(rel)
    record = _copies_file(wt) if made else None
    if record is not None:
        # without the record a copy reads as work: kept, never lost
        with contextlib.suppress(OSError):
            record.write_text(
                json.dumps({r: _digest(wt / r) for r in made}, indent=1),
                encoding="utf-8",
            )
    return made


def create(main: Path, key: str, start: str) -> tuple[Path | None, str, bool]:
    """The worktree for `key` on `worktree-<key>`, at its home, made from `start`, what happened, and
    whether it already existed (the one `git worktree list` lists, at its home or under
    `.claude/worktrees/`: the caller decides whose it is). (None, why, False) when refused."""
    if not WORKTREE_NAME.match(key):
        return None, f"{key!r} is not a worktree name (letters, digits, . _ -)", False
    there = agent_worktree(main, key)
    path = agents_home(main) / key
    if (
        there.is_dir()
        and not there.is_symlink()
        and is_listed(there, listed_worktrees(main))
    ):
        return there, f"{there} is a worktree of {main}", True
    if path.exists() or path.is_symlink():
        return (
            None,
            f"{path} exists and git lists no worktree of {main} there (a removed clone's "
            "worktree, or a copy): it is never reused. Move it aside or use another name",
            False,
        )
    why = home_refusal(main)
    if why:
        return None, why, False
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        return None, f"cannot make {path.parent}: {e}", False
    branch = f"worktree-{key}"
    if out(main, "rev-parse", "--verify", "--quiet", f"refs/heads/{branch}"):
        r = run(main, "worktree", "add", str(path), branch)
    else:
        r = run(main, "worktree", "add", str(path), "-b", branch, start)
    if r.returncode != 0:
        return None, f"git worktree add failed: {r.stderr.strip()}", False
    copied = copy_local(main, path)
    note = f"; copied the main checkout's {', '.join(copied)}" if copied else ""
    return path, f"created {path} on {branch}{note}", False
